CREATE TABLE IF NOT EXISTS kcrm_ticket_lock (id INTEGER PRIMARY KEY, touched INTEGER NOT NULL DEFAULT 0) ENGINE=InnoDB;
INSERT IGNORE INTO kcrm_ticket_lock(id,touched) VALUES(1,0);
CREATE TABLE IF NOT EXISTS kcrm_ticket_sources (id VARCHAR(64) PRIMARY KEY, name VARCHAR(250) NOT NULL, category VARCHAR(150) NOT NULL, address VARCHAR(500) NOT NULL, payload LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS kcrm_ticket_batches (id VARCHAR(64) PRIMARY KEY, source_id VARCHAR(64) NOT NULL, active INTEGER NOT NULL, payload LONGTEXT NOT NULL, FOREIGN KEY(source_id) REFERENCES kcrm_ticket_sources(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS kcrm_tickets (code VARCHAR(18) PRIMARY KEY, batch_id VARCHAR(64) NOT NULL, used_at VARCHAR(32) NULL, admission_id VARCHAR(64) NULL, payload LONGTEXT NOT NULL, FOREIGN KEY(batch_id) REFERENCES kcrm_ticket_batches(id), INDEX(batch_id), INDEX(used_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS kcrm_ticket_admissions (id VARCHAR(64) PRIMARY KEY, code VARCHAR(18) NOT NULL, admitted_at VARCHAR(32) NOT NULL, reversed_at VARCHAR(32) NULL, payload LONGTEXT NOT NULL, FOREIGN KEY(code) REFERENCES kcrm_tickets(code), INDEX(admitted_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS kcrm_ticket_requests (id VARCHAR(64) PRIMARY KEY, fingerprint VARCHAR(64) NOT NULL, response LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS kcrm_ticket_events (id VARCHAR(64) PRIMARY KEY, payload LONGTEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
